"""Check a pull request body before it becomes the squash commit (CONTRIBUTING.md,
"Commit messages"): the ``Release-Note:`` line is its last paragraph, and nothing in
it is an AI attribution that would ride into the commit.

Usage: ``python .github/scripts/check_pr_body.py`` with the body in ``PR_BODY``;
exits 1 with the reasons on stdout. With ``PR_NUMBER`` and ``GH_TOKEN`` set, the
footer the GitHub tool appends to every pull request it opens is first edited out of
the body with ``gh pr edit``, so the first run passes and no footer reaches the squash.
"""

from __future__ import annotations

import os
import re
import subprocess
import sys
from typing import List, Tuple

RELEASE_NOTE = re.compile(r"^Release-Note:\s*\S", re.MULTILINE)
# Trailers GitHub appends to, or keeps in, a squash commit; any of them after the
# Release-Note buries it, and all of them are attribution the repository refuses.
ATTRIBUTION = re.compile(
    r"^(Co-authored-by|Claude-Session):|Generated with \[Claude Code\]|claude\.ai/code",
    re.MULTILINE | re.IGNORECASE,
)


# The footer the GitHub tool appends to a body it sends, whatever the body said:
# a rule and one italic line. Only at the very end, and only this shape.
TOOL_FOOTER = re.compile(
    r"\s*\n---\s*\n_Generated by \[Claude Code\]\(https://claude\.ai/code/[^)\s]*\)_\s*\Z"
)

# The project's own two-line header on a pull request it opened: a marker comment
# and a "Requested by" line. Not attribution of the change; skipped before checking.
HEADER = re.compile(
    r"\A\s*<!--\s*claude-projects-attribution.*?-->\s*\n(_Requested by .*_\s*\n)?",
    re.DOTALL,
)


def without_tool_footer(body: str) -> Tuple[str, bool]:
    """*body* with the GitHub tool's footer taken off its end, and whether it was there."""
    text = body.replace("\r\n", "\n")
    stripped = TOOL_FOOTER.sub("", text)
    return stripped, stripped != text


def problems(body: str) -> List[str]:
    """Why *body* would make a bad squash commit; empty when it is fine."""
    text = HEADER.sub("", body.replace("\r\n", "\n")).strip()
    found: List[str] = []
    if ATTRIBUTION.search(text):
        found.append(
            "the body carries an AI attribution (Co-authored-by, Claude-Session or a "
            "Claude Code footer); remove it, it would ride into the squash commit"
        )
    notes = RELEASE_NOTE.findall(text)
    if not notes:
        found.append(
            "no `Release-Note:` line; add one as the last paragraph "
            "(`Release-Note: none` for a change no user would notice)"
        )
        return found
    paragraphs = [p for p in re.split(r"\n\s*\n", text) if p.strip()]
    last = paragraphs[-1].strip()
    if (
        not last.startswith("Release-Note:")
        or "\n" in last
        and not all(
            line.startswith(("Release-Note:", " ")) for line in last.splitlines()
        )
    ):
        found.append(
            "the `Release-Note:` line is not the last paragraph of the body, so git "
            "will not see it as a trailer; move it to the end"
        )
    return found


def edit_out_tool_footer(body: str) -> str:
    """Take the tool's footer off the pull request itself, when there is one and this
    run may edit it; the body as it now stands either way."""
    stripped, found = without_tool_footer(body)
    number = os.environ.get("PR_NUMBER")
    if not found or not number or not os.environ.get("GH_TOKEN"):
        return body
    done = subprocess.run(
        ["gh", "pr", "edit", number, "--body-file", "-"],
        input=stripped,
        text=True,
        capture_output=True,
    )
    if done.returncode != 0:
        print(f"Could not edit the tool's footer out: {done.stderr.strip()}")
        return body
    print("Edited the GitHub tool's footer out of the body.")
    return stripped


def main() -> int:
    body = edit_out_tool_footer(os.environ.get("PR_BODY", ""))
    found = problems(body)
    for line in found:
        print(f"- {line}")
    if found:
        print("\nSee CONTRIBUTING.md, 'Commit messages'.")
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
